// spec: .qa/e2e/specs/guided-prayer.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
// 2026-10-06 (#a5decf4a): у фрагмента, утверждённого в админке, вместо «הטקסט עדיין לא אושר…» — «מקור: … · אושר על ידי …».
import { SOURCE_LINE } from '../_helpers/prayer-nav';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 1440, height: 900 },
});

// Список ключей зафиксирован массивом (по данным приложения): базовое имя + варианты _ashkenaz/_sfarad.
// Несуществующий вариант отдаёт HTTP 404 и пропускается; shehecheyanu существует только в _sfarad.
const BASES = [
  'hamotzi',
  'mezonot',
  'hagefen',
  'haetz',
  'haadamah',
  'shehakol',
  'birkat_hamazon',
  'meein_shalosh',
  'borei_nefashot',
  'shehecheyanu',
  'asher_yatzar',
  'tefilat_haderech',
];
const SFARAD_ONLY = new Set(['shehecheyanu']);

const counterLocator = (page: Page) => page.getByText(/^\d+ מתוך \d+$/).first();

async function readCounter(page: Page): Promise<[number, number]> {
  if ((await counterLocator(page).count()) === 0) return [1, 1];
  const m = (await counterLocator(page).innerText()).match(/(\d+) מתוך (\d+)/)!;
  return [Number(m[1]), Number(m[2])];
}

test.describe('Молитва по шагам', () => {
  test('GP-05 Пояснение и строка источника во всех ברכות (/prayer/beracha_*) #6a86f7df @prod-safe @desktop', async ({ page }) => {
    // 1. test.slow(). Сохранить localStorage['prayer-progress'].
    test.slow();
    test.setTimeout(900_000);
    await page.goto('/home');
    await expect(page.getByRole('button', { name: 'התחל תפילה' })).toBeVisible({ timeout: 20_000 });
    const saved = await page.evaluate(() => localStorage.getItem('prayer-progress'));
    try {
      let totalKeys = 0;
      for (const base of BASES) {
        const keys = SFARAD_ONLY.has(base) ? [`beracha_${base}_sfarad`] : [`beracha_${base}_ashkenaz`, `beracha_${base}_sfarad`];
        for (const key of keys) {
          // 2–3. Открыть /prayer/<key>; «קודם» до «1 מתוך N»; на каждом фрагменте — пояснение и строка источника; «המשך» до конца.
          const response = await page.goto(`/prayer/${key}`);
          if (response && response.status() === 404) continue;
          totalKeys++;
          await expect(page.locator('#runner-section-info'), `${key}: страница открылась`).toBeVisible({ timeout: 20_000 });
          for (;;) {
            const [i, n] = await readCounter(page);
            if (i === 1) break;
            await page.getByRole('button', { name: 'קודם', exact: true }).click();
            await expect(counterLocator(page)).toHaveText(`${i - 1} מתוך ${n}`);
          }
          const [, total] = await readCounter(page);
          for (let i = 1; i <= total; i++) {
            if (total > 1) await expect(counterLocator(page), key).toHaveText(`${i} מתוך ${total}`);
            const info = page.locator('#runner-section-info');
            await expect(info, `${key} ${i}/${total}: #runner-section-info`).toBeVisible();
            await expect(page.locator('#runner-section-info-text'), `${key} ${i}/${total}: текст пояснения`).not.toHaveText('');
            await expect(info.locator('svg').first(), `${key} ${i}/${total}: иконка ⓘ`).toBeVisible();
            await expect(page.getByText(SOURCE_LINE), `${key} ${i}/${total}: строка источника`).toHaveCount(1);
            await expect(page.getByRole('button', { name: 'שיתוף התפילה' }), `${key} ${i}/${total}: нет «שיתוף התפילה»`).toHaveCount(0);
            // У ברכות нет «סיים תפילה»: на последнем фрагменте «המשך» отсутствует.
            if (i < total) await page.getByRole('button', { name: 'המשך', exact: true }).click();
          }
        }
      }
      expect(totalKeys).toBeGreaterThanOrEqual(1);
    } finally {
      // 4. Уборка: вернуть prayer-progress.
      await page.goto('/home');
      await page.evaluate((v) => {
        if (v === null) localStorage.removeItem('prayer-progress');
        else localStorage.setItem('prayer-progress', v);
      }, saved);
    }
  });
});
